#include <stdlib.h>
#include <string.h>

#define INF 1e30

// a: n x n cost matrix (row-major, double)
// returns assignment: for each column j, p[j] = row assigned (0-based)
// Actually e-maxx: p[j] = row i assigned to column j
void hungarian(int n, const double *a, int *p) {
    double *u = malloc((n+1) * sizeof(double));
    double *v = malloc((n+1) * sizeof(double));
    int *way = malloc((n+1) * sizeof(int));
    double *minv = malloc((n+1) * sizeof(double));
    char *used = malloc((n+1) * sizeof(char));

    for (int i = 0; i <= n; i++) { u[i] = 0; v[i] = 0; p[i] = 0; }

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = a[(i0-1)*n + (j-1)] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }

    // p[j] for j=1..n is the row assigned to column j
    free(u); free(v); free(way); free(minv); free(used);
}
```

