        for (int e = 0; e < k; e++) {
            double c = cost[i*k+e];
            if (c > maxc) maxc = c;
        }
    double eps = maxc;
    while (eps > eps_final) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; i++) unassigned[top++] = i;
        while (top > 0) {
            int i = unassigned[--top];
            double v1 = INF, v2 = INF;
            int j1 = -1;
            const int *ir = idx + i*k;
            const double *cr = cost + i*k;
            for (int e = 0; e < k; e++) {
                double v = cr[e] + prices[ir[e]];
                if (v < v1) { v2 = v1; v1 = v; j1 = ir[e]; }
                else if (v < v2) v2 = v;
            }
            if (v2 >= INF/2) prices[j1] += eps;
            else prices[j1] += (v2 - v1) + eps;
            if (owner[j1] != -1) unassigned[top++] = owner[j1];
            owner[j1] = i;
        }
        eps *= factor;
    }
    for (int i = 0; i < n; i++) {
        double v1 = INF;
        const int *ir = idx + i*k;
        const double *cr = cost + i*k;
        for (int e = 0; e < k; e++) {
            double v = cr[e] + prices[ir[e]];
            if (v < v1) v1 = v;
        }
        u[i] = v1;
    }
    free(unassigned);
}
